impl Solution{pub fn spiral_order(m:Vec<Vec<i32>>)->Vec<i32>{if m.is_empty(){return vec![]}let(mut t,mut b,mut l,mut r)=(0i32,m.len()as i32-1,0i32,m[0].len()as i32-1);let mut o=vec![];while t<=b&&l<=r{for j in l..=r{o.push(m[t as usize][j as usize]);}t+=1;for i in t..=b{o.push(m[i as usize][r as usize]);}r-=1;if t<=b{for j in (l..=r).rev(){o.push(m[b as usize][j as usize]);}b-=1;}if l<=r{for i in (t..=b).rev(){o.push(m[i as usize][l as usize]);}l+=1;}}o}}
